const orig=p.episodes.find(e=>e.sequences.some(s=>s.id==='camp-seq'))||p.episodes[0];
const episodes=[];
for(const a of ACTS){let e=a.id?p.episodes.find(x=>x.id===a.id):orig;if(!e){e={id:a.id,title:a.title,synopsis:a.synopsis,sequences:[],exports:[]};}e.title=a.title;e.synopsis=a.synopsis;e.exports??=[];
 const seqs=[];for(const s of a.sequences){let q=p.episodes.flatMap(x=>x.sequences).find(x=>x.id===s.id);if(!q)q={id:s.id,title:s.title,cast:[],shots:[],silent:true};q.title=s.title;if(s.location&&!q.location)q.location=s.location;q.minutes=s.minutes;q.text=s.text;q.coverPrompt=cover(s.id);seqs.push(q);}
 for(const q of e.sequences)if(!seqs.includes(q))seqs.push(q);e.sequences=seqs;episodes.push(e);}
for(const e of p.episodes)if(!episodes.includes(e))episodes.push(e);p.episodes=episodes;
save(p);
